"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.parse
import urllib.request


def _get_json(url, timeout=30):
    """GET a URL, retrying the identical request while rate limited."""
    while True:
        try:
            with urllib.request.urlopen(url, timeout=timeout) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            try:
                delay = float(exc.headers.get("Retry-After", "1"))
            except (TypeError, ValueError):
                delay = 1.0
            time.sleep(max(delay, 0.0))


def fetch_payouts(base_url):
    """Return every payout once, following v2 export windows to the end."""
    payouts = []
    seen = set()
    cursor = None
    while True:
        params = {"limit": 1000}
        if cursor is not None:
            params["cursor"] = cursor
        url = f"{base_url}/v2/payouts?{urllib.parse.urlencode(params)}"
        window = _get_json(url)
        # Adjacent windows overlap on their edge payout, so deduplicate by id.
        for payout in window["payouts"]:
            payout_id = payout["id"]
            if payout_id not in seen:
                seen.add(payout_id)
                payouts.append(payout)
        cursor = window["cursor"]
        if window["drained"]:
            return payouts


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    with open(args.out, "w") as f:
        for p in payouts:
            f.write(json.dumps(p) + "\n")
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

